package dev.thefoolish.generated.createanotepadappthatusesa;import android.widget.*;public final class EditorActivity extends AppScreen{private EditText titleField,bodyField;protected void render(){title("Editor");titleField=field("Document title");titleField.setText(store.text("draft_title",""));bodyField=new EditText(this);bodyField.setHint("Write here…");bodyField.setText(store.text("draft_body",""));bodyField.setTextColor(TEXT);bodyField.setHintTextColor(MUTED);bodyField.setGravity(android.view.Gravity.TOP);bodyField.setMinHeight(dp(220));body.addView(titleField);body.addView(bodyField);Button save=button("Save document");save.setOnClickListener(v->{String t=titleField.getText().toString().trim(),b=bodyField.getText().toString().trim();if(t.isEmpty()){titleField.setError("Enter a title");return;}if(b.isEmpty()){bodyField.setError("Write some content before saving");return;}String row=clean(t)+"|"+clean(b);String old=store.text("documents","");store.putText("documents",row+(old.isEmpty()?"":"\n"+old));store.putText("draft_title","");store.putText("draft_body","");titleField.setText("");bodyField.setText("");});body.addView(save);nav(new String[]{"Writing","Editor","Search","Library"},new Class[]{MainActivity.class,EditorActivity.class,SearchActivity.class,LibraryActivity.class});}protected void onPause(){super.onPause();if(titleField!=null)store.putText("draft_title",titleField.getText().toString());if(bodyField!=null)store.putText("draft_body",bodyField.getText().toString());}private String clean(String s){return s.replace("|","/").replace("\n"," ↵ ");}}